	public CUsuario() throws IOException, ClassNotFoundException, SQLException {
		usuarioPers = new PUsuario();
		ListaUsuarios=usuarioPers.ListaUsuarios();
		autentication = new Autenticacion();
	}
	
	public IUsuario crear(String nombre, String apellido1, String apellido2, String correo, String pwd, String confirmarContra, String dni, String rol) throws SQLException, ClassNotFoundException, IOException {
		Usuario usu = new Usuario(nombre, apellido1, apellido2, correo, pwd, confirmarContra, dni, rol);
		usuarioPers = new PUsuario();
		Usuario existe = buscarPorDNI(dni);
		if(existe == null) {
			try {
				if(nombre.equals("") || apellido1.equals("") || apellido2.equals("") || correo.equals("") || pwd.equals("") || confirmarContra.equals("") || dni.equals("")){return null;}
				else if(nombre.length()>30){return null;}
				else if(apellido1.length()>20 || apellido2.length()>20){return null;}
				else if(correo.length()>100){return null;}
				else if(pwd.length()>255 || confirmarContra.length()>255){return null;}
				else if(dni.length()!=9){return null;}
				else if(!(dni.charAt(8)>='a' && dni.charAt(8)<='z') && !(dni.charAt(8)>='A' && dni.charAt(8)<='Z')){return null;}
				//else if(rol.length()>15){return null;}
				else if((pwd.equals(confirmarContra))) {
					for (int i = 0;i<8;i++) { 
						if(dni.charAt(i)<'0' ||  dni.charAt(i)>'9') {
							return null;
						}
					}
					
				} if(autentication.existeCuentaUPM(correo)){
						String pwdcifrada = Cifrado.cifrar(pwd);
						usu.setPwd(pwdcifrada);
						UPMUsers recogeRol = ObtencionDeRol.get_UPM_AccountRol(correo);
						usu.setRol(recogeRol.name());
						usuarioPers.create(usu);
						return usu;
				} else {
					return null;
				}
			} catch (SQLException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}
		} else {
			return null;
		}
		return null;
	}
	
	public Usuario buscarPorDNI(String dni) throws SQLException{
		Usuario devolver=null;
		ListaUsuarios=usuarioPers.ListaUsuarios();
		for (Usuario aux : ListaUsuarios) {
			if(aux.getDNI().equalsIgnoreCase(dni))
				devolver = aux;
		}
		return devolver;
	}
	
	
	
	public void login(String dni) throws ClassNotFoundException, IOException, SQLException{
		Usuario usuario=null;
		usuario = buscarPorDNI(dni);
		App.GLOBAL_USUARIO = usuario;
		existeUsuarioBD(usuario);
	}
	
	public void existeUsuarioBD(Usuario usuario) throws IOException, ClassNotFoundException{
		if(usuario==null){
			GUILogin log = new GUILogin();
			log.setVisible(true);
		}else{
				String var = (usuario.getRol());
				if(var.equals("ALUMNO")) {
					GUIAlumno malumno = new GUIAlumno();
					malumno.setVisible(true);
				} else if (var.equals("PAS")) {
					GUIPAS mpas = new GUIPAS();
					mpas.setVisible(true);
				} else {
					GUIPDI mpdi = new GUIPDI();
					mpdi.setVisible(true);
				}
		}
	}
	
	public boolean ComprobarexisteCuentaUPM(String correo){
		return	autentication.existeCuentaUPM(correo);
	}

